#ifndef FOO_H
#define FOO_H
// Foo: a test class; the comment mentions a; and b;
class Foo
{
public:
    Foo() : a(0) {}
    virtual ~Foo() {}
    virtual void f();
    virtual void g();
    int getA() const { return a; }
    int getAOutOfLine() const;
    int pub;
protected:
    int a;
    short b[2];
    char *name;
};
#endif

