#include "Foo.h"
#define FIRST_B(p) ((p)->b[0])
int useA(Foo *p) { return p->getA() + 1; }
struct Peek : Foo { int sum(); int raw(); };
int Peek::sum() { return FIRST_B(this) + b[1]; }
int Peek::raw() { return a; }
int useB(Foo *p) { return static_cast<Peek *>(p)->sum(); }
int viaDerived(Peek *p) { return p->pub; }
int viaCall(Foo *p) { return p->getAOutOfLine(); }
int sizeOnly() { return sizeof(Foo); }
int sizeCond(Foo *p) { if (sizeof(Foo) > 20) return p->pub; return 0; }
void callG(Foo *p) { p->g(); }
void callF(Foo *p) { p->f(); }
